import unittest


def fruit_distribution(s, n):
    lis = list()
    for i in s.split(' '):
        if i.isdigit():
            lis.append(int(i))
    return n - sum(lis)


class TestFruitDistribution(unittest.TestCase):

    def test_basic(self):
        self.assertEqual(fruit_distribution("5 apples and 6 oranges", 19), 8)

    def test_zero_apples(self):
        self.assertEqual(fruit_distribution("0 apples and 1 oranges", 3), 2)

    def test_large_total(self):
        self.assertEqual(fruit_distribution("2 apples and 3 oranges", 100), 95)

    def test_multi_digit(self):
        self.assertEqual(fruit_distribution("100 apples and 1 oranges", 120), 19)

    def test_single_number(self):
        self.assertEqual(fruit_distribution("10 apples", 15), 5)

    def test_no_digits(self):
        self.assertEqual(fruit_distribution("apples and oranges", 7), 7)

    def test_all_digits(self):
        self.assertEqual(fruit_distribution("3 4", 10), 3)

    def test_result_zero(self):
        self.assertEqual(fruit_distribution("4 apples and 5 oranges", 9), 0)

    def test_mixed_text(self):
        self.assertEqual(fruit_distribution("apples 12 oranges 8 mangoes", 30), 10)


if __name__ == "__main__":
    unittest.main()
